),
calls AS (   -- successful transactions sent directly to a target
  SELECT tx.`hash` AS tx_hash, tx.block_number, tx.to_address AS target,
         CASE
           WHEN ARRAY_LENGTH(t.selectors) = 0 THEN IF(LENGTH(tx.input) >= 10, SUBSTR(tx.input, 1, 10), 'nodata')
           WHEN SUBSTR(tx.input, 1, 10) IN UNNEST(t.selectors) THEN SUBSTR(tx.input, 1, 10)
           ELSE 'other'
         END AS bucket
  FROM `bigquery-public-data.crypto_ethereum.transactions` tx
  JOIN targets t ON tx.to_address = t.address
  -- Literal constants (not DECLARE): a single statement, so the dry run gives the exact bytes and the daily
  -- partitions are pruned. Period: blocks 11,565,019 (2021-01-01 00:00:00) to 24,580,372 (2026-03-03 23:59:59)
  WHERE tx.block_timestamp BETWEEN TIMESTAMP('2021-01-01 00:00:00') AND TIMESTAMP('2026-03-03 23:59:59')
    AND tx.block_number BETWEEN 11565019 AND 24580372
    AND tx.receipt_status = 1
)
SELECT target, bucket,
       APPROX_COUNT_DISTINCT(tx_hash) AS transactions,
       COUNT(*) AS direct_frames,
       COUNT(*) AS frames,
       ARRAY_AGG(STRUCT(tx_hash, block_number, 0 AS depth, 'call' AS call_type)
                 ORDER BY FARM_FINGERPRINT(tx_hash) LIMIT 25) AS sample
FROM calls
GROUP BY target, bucket
ORDER BY target, transactions DESC;
